function patternInvertedAlphabetPyramid(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < i; j++) row += ' ';
    for (let j = 0; j < n - i; j++) row += String.fromCharCode(65 + j);
    for (let j = n - 2 - i; j >= 0; j--) row += String.fromCharCode(65 + j);
    rows.push(row);
  }
  return rows.join('\n');
}

