function patternInvertedAlphabetPyramid(n) {
  let alphabet = '';
  for (let i = 0; i < n; i++) alphabet += String.fromCharCode(65 + i);
  let rows = [];
  for (let i = 0; i < n; i++) {
    const spaces = ' '.repeat(i);
    const left = alphabet.slice(0, n - i);
    const right = left.split('').reverse().slice(1).join('');
    rows.push(spaces + left + right);
  }
  return rows.join('\n');
}
